import org.deeptimeline.app.*
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter
fun main(){val roman=TimeMath.parseCivil("-44-03-15","12:34:56.123456789");check(roman.year==-43&&roman.nano==123456789);check(TimeMath.formatCivil(roman)=="-0044-03-15T12:34:56.123456789");val bronze=TimeMath.parseCivil("-2500-08-19","06:30");check(bronze.year==-2499);check(TimeMath.parseCivil(TimeMath.formatCivil(bronze).substringBefore('T'),TimeMath.formatCivil(bronze).substringAfter('T'))==bronze);val paleo=TimeMath.parseCivil("-200000-01-01","00:00:00");check(paleo.year==-199999);check(TimeMath.formatCivil(paleo).startsWith("-200000-"));val remote=TimeMath.parseCivil("-1000000000-01-01","00:00");check(remote.year==-999999999);check(TimeMath.formatCivil(remote).startsWith("-1000000000-"));val bc=TimeMath.parseCivil("-1-12-31","00:00");val ad=TimeMath.parseCivil("1-01-01","00:00");check(bc.year==0&&ad.year==1);check(TimeMath.deltaSeconds(TimeMath.fromUtc(ad),TimeMath.fromUtc(bc))==86400.0);check(TimeMath.fromUtc(paleo)<TimeMath.fromUtc(bronze));check(TimeMath.fromUtc(bronze)<TimeMath.fromUtc(roman));check(TimeMath.fromUtc(roman)<TimeMath.fromUtc(ad));check(TimeMath.formatCivil(LocalDateTime.parse("0000-12-31T00:00",DateTimeFormatter.ISO_LOCAL_DATE_TIME))=="-0001-12-31T00:00");check(TimeMath.formatCivil(LocalDateTime.parse("-0044-03-15T12:00",DateTimeFormatter.ISO_LOCAL_DATE_TIME))=="-0045-03-15T12:00");for(d in listOf("0-01-01","-0-01-01","0000-01-01","-0000-01-01"))check(runCatching{TimeMath.parseCivil(d,"12:00")}.isFailure);check(runCatching{TimeMath.parseCivil("-44-02-30","12:00")}.isFailure);check(runCatching{TimeMath.parseCivil("-1000000001-01-01","12:00")}.isFailure);check(TimeMath.parseCivil("+10000-12-31","12:00").year==10000);println("BCE calendar notation, epoch ordering, migration mapping, year boundary, deep prehistory: PASS")}
